    --yagr-legend-item-hidden: var(--g-color-text-hint);
}

/*
 * Тултип Yagr рендерится в document.body, поэтому темизируется через собственный класс,
 * переданный опцией tooltip.className (а не через внутреннюю разметку).
 */
.yagr-tooltip.cpu-load-chart__tooltip {
    --yagr-tooltip-font-family: var(--g-font-family-sans);
    color: var(--g-color-text-primary);
    background-color: var(--g-color-base-float);
    border-radius: var(--g-border-radius-m);
    box-shadow: 0 2px 8px var(--g-color-sfx-shadow);
}

