args.command:
rm -rf dist && mkdir -p /tmp/cpucheck && cat > /tmp/cpucheck/source.test.ts <<'EOF'
import {expect, test, vi} from 'vitest';
import {createMockCpuLoadSource} from '/home/sandbox/workspace/src/monitoring/cpuLoadSource';

test('history + live are contiguous', async () => {
  vi.useFakeTimers({now: 1_700_000_000_500});
  const src = createMockCpuLoadSource({latencyMs: 10});
  const to = Date.now();
  const p = src.loadHistory({from: to - 86_400_000, to, signal: new AbortController().signal});
  const got: number[] = [];
  const unsub = src.subscribe((b) => got.push(...b.timeline));
  await vi.advanceTimersByTimeAsync(3000);
  const h = await p;
  console.log('points', h.timeline.length, 'min', Math.min(...h.values), 'max', Math.max(...h.values));
  expect(h.timeline.length).toBe(86_400);
  expect(got[0]).toBe(h.timeline.at(-1)! + 1000);
  unsub();
  const n = got.length;
  await vi.advanceTimersByTimeAsync(3000);
  expect(got.length).toBe(n);
});

test('abort rejects', async () => {
  const src = createMockCpuLoadSource({latencyMs: 50});
  const c = new AbortController();
  const p = src.loadHistory({from: 0, to: 1000, signal: c.signal});
  c.abort();
  await expect(p).rejects.toThrow('Aborted');
});
EOF
npx vitest run --root /tmp/cpucheck 2>&1 | tail -15

